WITH unpacked AS (SELECT id, created_at, coupon_codes, ship_to, attributes['utm_source'] AS utm_source, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, COALESCE(attributes['device'], 'unknown') AS device_or_default FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) AS row_count, MAX(created_at) AS last_seen, MAX(created_at) AS last_seen_2 FROM unpacked GROUP BY DATE_TRUNC('DAY', created_at) HAVING row_count > 1 ORDER BY activity_day ASC
